import React, { useEffect } from 'react';
import { useMap } from 'react-leaflet';
import { GeoSearchControl, OpenStreetMapProvider } from 'leaflet-geosearch';
import 'leaflet-geosearch/dist/geosearch.css';

const LeafletGeocoder = ({ onLocationFound }) => {
  const map = useMap();

  useEffect(() => {
    if (!map) return;

    // Create the search provider and control
    const provider = new OpenStreetMapProvider();
    const geosearchControl = new GeoSearchControl({
      provider,
      style: 'bar',
      showMarker: false, // We'll handle the marker ourselves
      showPopup: false,
      autoClose: true,
      retainZoomLevel: false,
      animateZoom: true,
      keepResult: true,
      searchLabel: 'Search for a location...',
      updateMap: false // We'll update position manually
    });

    // Add the control to the map
    map.addControl(geosearchControl);

    // Listen for location selection
    const handleSearchResult = (event) => {
      const { location } = event;
      if (location) {
        // Call the callback with the new coordinates
        onLocationFound({
          latitude: location.y,
          longitude: location.x
        });
        
        // Animate map to the new location
        map.flyTo([location.y, location.x], 14);
      }
    };

    // Event listener for geosearch results
    map.on('geosearch/showlocation', handleSearchResult);

    // Cleanup
    return () => {
      map.off('geosearch/showlocation', handleSearchResult);
      map.removeControl(geosearchControl);
    };
  }, [map, onLocationFound]);

  return null; // This component doesn't render anything
};

export default LeafletGeocoder;
